package edu.psu.se411.cybertrack.model;

import java.time.LocalDate;
import java.time.LocalDateTime;

import org.springframework.data.annotation.Id;

/**
 * A firewall device stored in the "firewall" table.
 * Spring Data JDBC maps camelCase components to snake_case columns (ipAddress -> ip_address).
 * The id is generated by the database; the frontend displays it as an Asset ID such as FW-0007.
 */
public record Firewall(
		@Id Long id,
		String name,
		String manufacturer,
		String model,
		String serialNumber,
		String ipAddress,
		String location,
		String status,
		String firmwareVersion,
		LocalDate purchaseDate,
		String notes,
		LocalDateTime createdAt,
		LocalDateTime updatedAt) {
}
